window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[185]={"id":"185","numero":185,"titre":"Réaction inflammatoire","objectifs":[{"id":"185-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la réaction inflammatoire","contenu":"<p>La <span class=\"kw-def\">réaction inflammatoire</span> est un <span class=\"kw-def\">processus de défense de l'immunité naturelle</span> (<span class=\"kw-def\">immunité innée</span>), secondaire à une <strong>agression exogène ou endogène</strong>. Elle constitue la <span class=\"kw-chiffre\">première ligne</span> de réponse de l'organisme et se met en place en <span class=\"kw-chiffre\">quelques heures</span>.</p>\n      <ul>\n        <li>Ses <strong>déterminants biologiques</strong> peuvent donner des <span class=\"kw-clinique\">symptômes cliniques</span>, et à long terme des <span class=\"kw-alerte\">complications</span>.</li>\n        <li><strong>Quantifiable dans <span class=\"kw-clinique\">les</span> liquides biologiques</strong>, surtout dans le <span class=\"kw-bio\">sang</span>.</li>\n        <li>Peut être <strong>localisée ou systémique</strong>.</li>\n        <li>Peut être <strong>aiguë ou chronique</strong>.</li>\n      </ul>","frequence":0},{"id":"185-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes aboutissant à l’inflammation et les principaux médiateurs impliqués","contenu":"<p>La réaction <span class=\"kw-etio\">inflammatoire</span> fait partie de l'<span class=\"kw-def\">immunité innée</span> et se déroule en <strong>trois phases successives</strong>.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Mécanismes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Initiation</strong></td><td>Libération de substances de défense qui : favorisent l'<span class=\"kw-def\">activation et le recrutement des cellules inflammatoires</span> ; augmentent la <span class=\"kw-def\">vasodilatation</span>, l'expression des <span class=\"kw-def\">molécules d'adhérence</span> et la <span class=\"kw-def\">perméabilité capillaire</span> ; ont un <span class=\"kw-clinique\">effet nociceptif</span></td></tr>\n          <tr><td><strong>Amplification</strong></td><td>Recrutement rapide des <span class=\"kw-def\">cellules phagocytaires</span> (<span class=\"kw-bio\">polynucléaires neutrophiles</span>) → phagocytose des pathogènes et des cellules infectées ou lésées ; puis activation secondaire des <span class=\"kw-def\">macrophages</span> → action sur la phase vasculaire, phagocytose, initiation de la <span class=\"kw-def\">réponse immunitaire spécifique</span></td></tr>\n          <tr><td><strong>Réparation</strong></td><td>Sous contrôle des <span class=\"kw-def\">cytokines anti-inflammatoires</span> et des facteurs de croissance : élimination des cellules lésées (phagocytose) ; <span class=\"kw-def\">cicatrisation</span> (fibrose, angiogenèse) ; régénération</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/185/phases-inflammation.png\" alt=\"Schéma des trois phases de la réaction inflammatoire : initiation, amplification et réparation, avec les cellules et médiateurs impliqués à chaque étape\" loading=\"lazy\">\n        <figcaption>Réaction <span class=\"kw-etio\">inflammatoire</span> et ses trois phases successives : initiation (vasodilatation, augmentation de la perméabilité capillaire, libération des médiateurs de défense), amplification (recrutement des <span class=\"kw-bio\">polynucléaires neutrophiles</span> puis des macrophages, phagocytose) et réparation (fibrose, angiogenèse, régénération). Source : fiche source EDN item 185.</figcaption>\n      </figure>\n      <p>De nombreux <span class=\"kw-def\">médiateurs</span> orchestrent ces phases :</p>\n      <table >\n        <thead><tr><th>Médiateur</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Amines vasoactives</span><br>(histamine, sérotonine, bradykinine)</td><td>Vasodilatation et augmentation de la perméabilité capillaire ; <span class=\"kw-clinique\">effet nociceptif</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Médiateurs lipidiques</span><br>(phospholipase A2, COX-1/COX-2, lipo-oxygénase)</td><td><strong>Prostaglandines :</strong> vasodilatation et augmentation de la perméabilité capillaire<br><strong>Leucotriènes :</strong> chimiotactiques</td></tr>\n          <tr><td><span class=\"kw-bio\">Protéases</span><br>(plasmine, trypsine, métalloprotéases, granzyme B)</td><td>Activent le <span class=\"kw-def\">complément</span> ; activent la <span class=\"kw-ttt\">fibrinolyse</span> ; favorisent la migration cellulaire dans la matrice extracellulaire</td></tr>\n          <tr><td><span class=\"kw-bio\">Protéines du complément</span></td><td><strong>Anaphylatoxines (C3a, C4a, C5a) :</strong> induisent l'inflammation<br><strong>C3b :</strong> opsonisation<br><strong>Complexe d'attaque membranaire (C5b-C9) :</strong> destruction des pathogènes ou des cellules</td></tr>\n          <tr><td><span class=\"kw-bio\">Protéines produites par le foie</span><br>(<span class=\"kw-bio\">CRP</span>, SAA, α1-antitrypsine, <span class=\"kw-bio\">haptoglobine</span>, <span class=\"kw-bio\">fibrinogène</span>, céruléoplasmine)</td><td>Rôle d'<span class=\"kw-def\">opsonine</span> ; activent le <span class=\"kw-bio\">complément</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Cytokines pro-inflammatoires</span><br>(IL-6, TNFα, IL-1α, IL-1β, IFNα, IFNβ, IL-12, IL-17, IL-23)</td><td>Produites surtout par <span class=\"kw-clinique\">les</span> <strong>macrophages</strong> (TNFα, IL-1) et les <strong><span class=\"kw-bio\">lymphocytes</span> Th17</strong> (IL-17). Actions :<br><strong>Cerveau :</strong> <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">asthénie</span>, somnolence ; sécrétion de CRF puis d'<span class=\"kw-bio\">ACTH</span><br><strong>Endothélium :</strong> augmentation de l'adhésivité vasculaire → migration des <span class=\"kw-bio\">leucocytes</span> → signes inflammatoires locaux<br><strong>Foie :</strong> production des protéines de l'inflammation</td></tr>\n          <tr><td><span class=\"kw-bio\">Cytokines anti-inflammatoires</span><br>(IL-4, IL-10, TGFβ)</td><td>Produites surtout par <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-bio\">lymphocytes</span> Th2</strong> ; limitent et résolvent la réaction</td></tr>\n          <tr><td><span class=\"kw-bio\">Chimiokines</span></td><td>Activation cellulaire et migration des <span class=\"kw-bio\">leucocytes</span> (récepteur couplé à protéine G)</td></tr>\n          <tr><td><span class=\"kw-bio\">Radicaux libres et NO</span></td><td>Action protectrice contre l'agent <span class=\"kw-etio\">infectieux</span>, parfois délétère pour <span class=\"kw-clinique\">les</span> cellules du site <span class=\"kw-etio\">inflammatoire</span></td></tr>\n          <tr><td><span class=\"kw-def\">Inflammasome</span></td><td>Stimulus intracellulaire → oligomérisation de protéines → active la <span class=\"kw-def\">caspase 1</span> (IL-1β convertase) → transforme la pro-IL-1β en <span class=\"kw-bio\">IL-1β mature</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Système de la coagulation</span></td><td>Participe à la réaction <span class=\"kw-etio\">inflammatoire</span> et au confinement de l'agression</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> médiateurs sont soit <strong>préformés</strong> — stockés dans les granules des <span class=\"kw-bio\">leucocytes</span> et des <span class=\"kw-bio\">plaquettes</span>, libérés rapidement par les tissus lésés ou stressés (histamine, sérotonine, enzymes) — soit <strong>néoformés</strong>, produits sur place par les cellules du site <span class=\"kw-etio\">inflammatoire</span> (cytokines, chimiokines, bradykinine).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 189 — Déficit immunitaire</em></p>","frequence":0},{"id":"185-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’inflammation et leurs conséquences","contenu":"<table >\n        <thead><tr><th>Type</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Signes locaux</strong><br>(visibles seulement si l'organe touché est superficiel — articulation, peau)</td><td><strong>Douleur</strong> (<em>dolor</em>) : médiateurs stimulant <span class=\"kw-clinique\">les</span> voies nociceptives (<span class=\"kw-bio\">bradykinine</span>)<br><strong>Chaleur</strong> (<em>calor</em>), <strong>rougeur</strong> (<em>rubor</em>), <strong>gonflement</strong> (<em>tumor</em>) : médiateurs vasoactifs</td></tr>\n          <tr><td><strong>Signes généraux</strong></td><td><span class=\"kw-clinique\">Fièvre</span> : action des cytokines sur l'hypothalamus<br><span class=\"kw-clinique\">Altération de l'état général</span> si inflammation prolongée : <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">asthénie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Mnémo.</strong> <span class=\"kw-clinique\">Les</span> <strong>4 signes cardinaux de Celse</strong> : <em>dolor, calor, rubor, tumor</em> (douleur, chaleur, rougeur, gonflement). L'<span class=\"kw-clinique\">altération de l'état général</span> retient les <strong>« 3 A »</strong> : <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">asthénie</span>.</div>","frequence":0},{"id":"185-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux marqueurs biologiques d’un syndrome inflammatoire","contenu":"<div class=\"callout callout-info\"><strong>Démarche en pratique courante.</strong> En <strong>1ʳᵉ intention</strong> : <span class=\"kw-bio\">hémogramme</span> + <span class=\"kw-bio\">CRP</span> ± <span class=\"kw-bio\">VS</span> (selon <span class=\"kw-clinique\">les</span> centres). En <strong>2ⁿᵈᵉ intention</strong> : <span class=\"kw-bio\">électrophorèse des protéines sériques</span>.</div>\n      <table >\n        <thead><tr><th>Marqueur</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">CRP</span><br>(C-Reactive Protein)</td><td>Protéine produite par le foie ; <strong>élévation rapide</strong> (<span class=\"kw-chiffre\">6-12 h</span>) ; <strong>demi-vie courte</strong> (<span class=\"kw-chiffre\">24 h</span>) ; marqueur de référence du <span class=\"kw-def\">syndrome inflammatoire</span><br><span class=\"kw-alerte\">Peut être augmentée en cas d'obésité</span> (jusqu'à <span class=\"kw-chiffre\">30 mg/L</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">VS</span><br>(<span class=\"kw-bio\">vitesse de sédimentation</span>)</td><td>Marqueur de <strong>cinétique lente</strong> (demi-vie <span class=\"kw-chiffre\">4-6 jours</span>) ; technique de mesure de référence = <span class=\"kw-def\">Westergren</span> ; <span class=\"kw-chiffre\">sensibilité 50 %</span>, <span class=\"kw-chiffre\">spécificité 97 %</span><br>Valeurs normales selon l'âge et le sexe : homme = <span class=\"kw-chiffre\">âge/2</span> ; femme = <span class=\"kw-chiffre\">(âge + 10)/2</span><br>De moins en moins réalisée (cinétique lente, mauvaise spécificité) ; garde un intérêt dans <span class=\"kw-clinique\">les</span> rhumatismes inflammatoires chroniques (<span class=\"kw-def\">score</span> <span class=\"kw-bio\">DAS28</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">Procalcitonine</span></td><td>Cinétique <strong>très rapide</strong> dès <span class=\"kw-chiffre\">H3</span> (demi-vie <span class=\"kw-chiffre\">&lt; 24 h</span>) ; marqueur d'inflammation d'origine <span class=\"kw-etio\">infectieuse</span> — <span class=\"kw-etio\">bactérienne</span>, parasitaire systémique (<span class=\"kw-clinique\">paludisme</span>) ou fongique<br><span class=\"kw-alerte\">N'augmente pas ou peu</span> lors des infections virales, des infections cloisonnées (<span class=\"kw-clinique\">abcès</span>) ni des maladies inflammatoires<br>Utile en <span class=\"kw-alerte\">urgence</span> : sa valeur initiale a une <strong>valeur pronostique</strong> dans le <span class=\"kw-alerte\">sepsis</span></td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-bio\">VS</span> peut être modifiée <strong>en dehors</strong> de tout <span class=\"kw-def\">syndrome inflammatoire</span> — d'où l'intérêt de la coupler à une électrophorèse :</p>\n      <table >\n        <thead><tr><th>Facteur</th><th><span class=\"kw-bio\">VS</span> augmentée</th><th><span class=\"kw-bio\">VS</span> diminuée</th></tr></thead>\n        <tbody>\n          <tr><td>Globules rouges</td><td>Anémie, hémolyse (test de Coombs direct positif)</td><td>Polyglobulie (la <span class=\"kw-bio\">VS</span> varie à l'inverse de l'<span class=\"kw-bio\">hématocrite</span>)</td></tr>\n          <tr><td>Secteur extracellulaire</td><td>Hémodilution : fin de <span class=\"kw-ci\">grossesse</span>, <span class=\"kw-def\">insuffisance cardiaque</span></td><td>Hémoconcentration</td></tr>\n          <tr><td><span class=\"kw-bio\">VGM</span></td><td>Macrocytose</td><td>Microcytose, drépanocytose</td></tr>\n          <tr><td>Poids</td><td><span class=\"kw-def\">Diabète</span>, <span class=\"kw-etio\">hypercholestérolémie</span>, <span class=\"kw-etio\">obésité</span></td><td><span class=\"kw-clinique\">Cachexie</span></td></tr>\n          <tr><td>Autres</td><td><span class=\"kw-ci\">Insuffisance rénale</span>, <span class=\"kw-def\">syndrome néphrotique</span>, <span class=\"kw-alerte\">hypergammaglobulinémie</span> monoclonale ou polyclonale</td><td>Hyperviscosité, hyperleucocytose <span class=\"kw-chiffre\">&gt; 50 G/L</span>, hypofibrinogénémie <span class=\"kw-etio\">congénitale</span>, <span class=\"kw-alerte\">cryoglobulinémie</span>, <span class=\"kw-ttt\">corticothérapie</span> à fortes doses</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Exploration du <span class=\"kw-bio\">complément</span></strong> (rang C). <span class=\"kw-bio\">C3</span> et <span class=\"kw-bio\">C4</span> sont fréquemment <strong>élevés</strong> lors de la réponse <span class=\"kw-etio\">inflammatoire</span>. Le <span class=\"kw-bio\">CH50</span> est <strong>diminué</strong> en cas de consommation par activation de la voie classique (<span class=\"kw-def\">lupus</span>, <span class=\"kw-def\">endocardite</span>, glomérulonéphrite) ou de déficit <span class=\"kw-etio\">génétique</span>.</div>","frequence":7},{"id":"185-5","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître la cinétique des principaux marqueurs de l’inflammation permettant de suivre son évolution","contenu":"<p>Pour <strong>suivre l'<span class=\"kw-clinique\">évolution</span></strong> d'un <span class=\"kw-def\">syndrome inflammatoire</span>, on associe deux protéines de <strong>cinétiques différentes</strong>.</p>\n      <table >\n        <thead><tr><th>Sens</th><th>Protéines</th><th>Amplitude</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"3\"><strong>Protéines qui augmentent</strong></td><td><span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">SAA</span></td><td><span class=\"kw-chiffre\">× 500</span></td></tr>\n          <tr><td><span class=\"kw-bio\">α1</span>, <span class=\"kw-bio\">α2</span>, <span class=\"kw-bio\">fibrinogène</span></td><td><span class=\"kw-chiffre\">× 3</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Céruléoplasmine</span>, <span class=\"kw-bio\">C3</span>, <span class=\"kw-bio\">C4</span></td><td><span class=\"kw-chiffre\">× 1,4</span></td></tr>\n          <tr><td><strong>Protéines qui diminuent</strong></td><td><span class=\"kw-bio\">Albumine</span>, <span class=\"kw-bio\">transferrine</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Marqueur</th><th>Cinétique</th><th>Demi-vie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Procalcitonine</span></td><td>Très rapide (dès <span class=\"kw-chiffre\">H3</span>)</td><td><span class=\"kw-chiffre\">&lt; 24 h</span></td></tr>\n          <tr><td><span class=\"kw-bio\">CRP</span></td><td>Rapide</td><td><span class=\"kw-chiffre\">24 h</span></td></tr>\n          <tr><td><span class=\"kw-bio\">VS</span></td><td>Lente</td><td><span class=\"kw-chiffre\">4-6 jours</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-bio\">CRP</span>, à demi-vie courte, permet un <strong><span class=\"kw-def\">suivi</span> rapproché et précoce</strong> de l'<span class=\"kw-clinique\">évolution</span>. La <span class=\"kw-bio\">VS</span>, à cinétique lente, reste élevée longtemps après la résolution : peu adaptée au suivi rapproché.</div>","frequence":0},{"id":"185-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations biologiques de la réaction inflammatoire","contenu":"<h4>Anémie <span class=\"kw-etio\">inflammatoire</span></h4>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span>.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">cytokines</span> de l'inflammation (<span class=\"kw-bio\">IL-1</span>, <span class=\"kw-bio\">TNFα</span>, <span class=\"kw-bio\">IFNγ</span>) entraînent : inhibition de l'<span class=\"kw-def\">érythropoïèse</span> ; diminution de la synthèse et de l'action de l'<span class=\"kw-bio\">EPO</span> ; augmentation de la synthèse hépatique d'<span class=\"kw-bio\">hepcidine</span>, qui <strong>piège le fer dans les macrophages</strong>. S'y ajoute une augmentation de l'<span class=\"kw-def\">érythrophagocytose</span> par les macrophages (diminution de la demi-vie des globules rouges).</p>\n      <p><strong>Présentation.</strong> Anémie d'abord <strong>modérée, normocytaire et normochrome</strong> ; après <span class=\"kw-chiffre\">6-8 semaines</span>, apparition d'une microcytose discrète (rarement <span class=\"kw-chiffre\">&lt; 70 fl</span>) et d'une hypochromie.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Anémie ferriprive</th><th>Anémie <span class=\"kw-etio\">inflammatoire</span></th><th>Anémie mixte</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Fer sérique</span></td><td>↓</td><td>↓</td><td>↓</td></tr>\n          <tr><td><span class=\"kw-bio\">Ferritinémie</span></td><td>↓</td><td>↑</td><td>↓, ↔ ou ↑</td></tr>\n          <tr><td><span class=\"kw-bio\">Transferrine</span></td><td>↑</td><td>↓</td><td>↑, ↔ ou ↓</td></tr>\n          <tr><td><span class=\"kw-bio\">CTF</span> (capacité totale de fixation)</td><td>↑</td><td>↓</td><td>↑, ↔ ou ↓</td></tr>\n          <tr><td><span class=\"kw-bio\">Coefficient de saturation</span></td><td>↓</td><td>↓</td><td>↓</td></tr>\n          <tr><td><span class=\"kw-bio\">Récepteur soluble de la transferrine</span> (RsTF)</td><td>↑</td><td>↔</td><td>↑</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Dans l'<strong>anémie mixte</strong> (carence martiale + <span class=\"kw-def\">syndrome inflammatoire</span>), l'augmentation du <span class=\"kw-bio\">récepteur soluble de la transferrine</span> permet de diagnostiquer la carence martiale associée — ce que ne permet pas la <span class=\"kw-bio\">ferritinémie</span>, dont l'élévation masque la carence. Donnée toutefois discutée.</div>\n      <h4><span class=\"kw-bio\">Hémogramme</span></h4>\n      <table >\n        <thead><tr><th>Lignée</th><th>Anomalie</th></tr></thead>\n        <tbody>\n          <tr><td>Globules rouges</td><td>Anémie : normocytaire/normochrome, puis microcytaire/hypochrome après <span class=\"kw-chiffre\">6-8 semaines</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Plaquettes</span></td><td><span class=\"kw-bio\">Thrombocytose</span> (via l'<span class=\"kw-bio\">IL-6</span>), proportionnelle à la durée de la réaction <span class=\"kw-etio\">inflammatoire</span> (jusqu'à <span class=\"kw-chiffre\">1000 G/L</span>)</td></tr>\n          <tr><td>Formule leucocytaire</td><td><strong>PNN :</strong> marqueur très précoce, surtout si cause <span class=\"kw-etio\">bactérienne</span><br><strong>Monocytose :</strong> marqueur précoce, surtout si cause bactérienne<br><strong>Leucopénie :</strong> possible, notamment au cours d'un <span class=\"kw-def\">sepsis</span><br><strong>Éosinopénie + leucocytose <span class=\"kw-chiffre\">&gt; 10 G/L</span> :</strong> infection bactérienne ou <span class=\"kw-ttt\">corticoïdes</span></td></tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-bio\">Électrophorèse des protéines sériques</span></h4>\n      <ul>\n        <li><span class=\"kw-bio\">Hypoalbuminémie</span>.</li>\n        <li><strong>Hyper-α1-globulinémie</strong> et <strong>hyper-α2-globulinémie</strong>, avec <span class=\"kw-chiffre\">α2 &gt; α1</span>.</li>\n        <li><span class=\"kw-bio\">β-globulines</span> inchangées ou légèrement diminuées (baisse de la <span class=\"kw-bio\">transferrine</span>).</li>\n        <li>Migration du <span class=\"kw-bio\">fibrinogène</span> en β et de la <span class=\"kw-bio\">CRP</span> en γ : peu d'influence sur le tracé.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":5},{"id":"185-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les protéines inflammatoires","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">protéines de l'inflammation</span> sont synthétisées par le <strong>foie</strong> sous l'effet des <span class=\"kw-bio\">cytokines pro-inflammatoires</span> ; elles ont un rôle d'<span class=\"kw-def\">opsonine</span> et activent le <span class=\"kw-def\">complément</span>.</p>\n      <table >\n        <thead><tr><th>Sens</th><th>Protéines</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Concentration augmentée</strong></td><td><span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">fibrinogène</span> ; <span class=\"kw-bio\">céruléoplasmine</span> ; <span class=\"kw-bio\">orosomucoïde</span> ; <span class=\"kw-bio\">haptoglobine</span> ; <span class=\"kw-bio\">ferritine</span> ; <span class=\"kw-bio\">α1-antitrypsine</span> et <span class=\"kw-bio\">α1-antichymotrypsine</span> ; <span class=\"kw-bio\">SAA</span> (sérum amyloïde A)</td></tr>\n          <tr><td><strong>Concentration diminuée</strong></td><td><span class=\"kw-bio\">Albumine</span> ; <span class=\"kw-bio\">transferrine</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Focus <span class=\"kw-bio\">CRP</span>.</strong> Élévation rapide (<span class=\"kw-chiffre\">6-12 h</span>), demi-vie courte (<span class=\"kw-chiffre\">24 h</span>) : c'est la protéine de référence du <span class=\"kw-def\">syndrome inflammatoire</span>. <span class=\"kw-alerte\">Peut être augmentée en cas d'obésité</span> (jusqu'à <span class=\"kw-chiffre\">30 mg/L</span>).</div>","frequence":0},{"id":"185-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies","contenu":"<table >\n        <thead><tr><th>Étiologie</th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Causes infectieuses</span></td><td>Représentent <span class=\"kw-chiffre\">50 %</span> des syndromes inflammatoires</td></tr>\n          <tr><td><span class=\"kw-etio\">Causes tumorales</span></td><td>Hémopathies ou cancers solides</td></tr>\n          <tr><td><span class=\"kw-etio\">Maladies inflammatoires et auto-immunes</span></td><td>Connectivites, rhumatismes inflammatoires, vascularites</td></tr>\n          <tr><td><span class=\"kw-etio\">Thromboses vasculaires</span></td><td>—</td></tr>\n          <tr><td><span class=\"kw-etio\">Maladies génétiques</span><br>(syndromes auto-inflammatoires)</td><td>Dues à une anomalie de l'<span class=\"kw-def\">immunité innée</span> : fièvres récurrentes inexpliquées, associées à des manifestations articulaires et cutanées (<span class=\"kw-clinique\">placard</span> érysipéloïde), des sérites et des signes abdominaux. Principalement : <strong><span class=\"kw-clinique\">fièvre</span> méditerranéenne familiale (FMF)</strong> et <strong>TRAPS</strong> (<em>TNF Receptor-Associated Periodic Syndrome</em>)</td></tr>\n          <tr><td><span class=\"kw-etio\">Médicaments</span></td><td>—</td></tr>\n          <tr><td><span class=\"kw-etio\">Traumatismes</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n      <h4>Bilan paraclinique d'un <span class=\"kw-def\">syndrome inflammatoire</span> prolongé inexpliqué</h4>\n      <p>Son exploration <strong>recouvre celle d'une <span class=\"kw-clinique\">fièvre</span> prolongée inexpliquée</strong>. Elle se conduit en deux temps.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>1ʳᵉ intention</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-bio\">NFS</span> ; bilans hépatique et rénal ; <span class=\"kw-bio\">protéinurie des 24 heures</span></td></tr>\n          <tr><td><strong>Imagerie</strong></td><td><span class=\"kw-imagerie\">Radiographie thoracique</span> ; <span class=\"kw-imagerie\">radiographie</span> des sinus et <span class=\"kw-imagerie\">panoramique dentaire</span> ; <span class=\"kw-imagerie\">radiographie</span> des articulations sacro-iliaques ; <span class=\"kw-imagerie\">échographie abdominale et pelvienne</span></td></tr>\n          <tr><td><strong>Microbiologie</strong></td><td>Tests de production d'<span class=\"kw-bio\">interféron gamma</span> (IGRA) et <span class=\"kw-clinique\">IDR</span> à la tuberculine ; <span class=\"kw-bio\">ECBU</span> ; <span class=\"kw-bio\">sérologies</span> répétées à 15 j d'intervalle (mycoplasmes, brucelle, légionelles, <em>Coxiella</em>, <span class=\"kw-etio\">VIH</span>, CMV, EBV) ; <span class=\"kw-bio\">hémocultures</span> systématiques</td></tr>\n          <tr><td><strong>Selon le contexte</strong></td><td><span class=\"kw-bio\">Anticorps antinucléaires</span> (<span class=\"kw-bio\">AAN</span>), <span class=\"kw-bio\">facteur rhumatoïde</span>, <span class=\"kw-bio\">CH50</span> et fractions du <span class=\"kw-bio\">complément</span> ; dosage du <span class=\"kw-bio\">PSA</span> chez l'homme</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Domaine</th><th>2ⁿᵈᵉ intention</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Imagerie</strong></td><td><span class=\"kw-imagerie\">ETT ± ETO</span> ; <span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvien</span> ; <span class=\"kw-imagerie\">TEP-scan</span></td></tr>\n          <tr><td><strong>Endoscopies</strong></td><td>Endoscopies digestives ; <span class=\"kw-imagerie\">fibroscopie</span> bronchique ± <span class=\"kw-bio\">LBA</span></td></tr>\n          <tr><td><strong>Recherche de <span class=\"kw-def\">tuberculose</span></strong></td><td>Recherche de bacilles tuberculeux (crachats, selles, moelle osseuse)</td></tr>\n          <tr><td><strong>Hématologie</strong></td><td><span class=\"kw-bio\">Biopsie ostéomédullaire</span> et myélogramme ± mycultures</td></tr>\n          <tr><td><strong>Neurologie</strong></td><td><span class=\"kw-bio\">ENMG</span> des membres</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Vascularite</span></strong></td><td><span class=\"kw-bio\">Biopsie d'artère temporale</span> si patient <span class=\"kw-chiffre\">&gt; 60 ans</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 190 — <span class=\"kw-clinique\">Fièvre</span> prolongée · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 193 — <span class=\"kw-def\">Vascularite</span> systémique · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 320 — Myélome multiple des os</em></p>","frequence":0},{"id":"185-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les mécanismes et les causes d’un syndrome inflammatoire dissocié","contenu":"<p>Un <span class=\"kw-def\">syndrome inflammatoire dissocié</span> correspond à des <strong>résultats discordants</strong> : un marqueur reste normal alors qu'un autre est anormal (ou inversement).</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Mécanisme / dissociation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Hémolyse</span></td><td>Diminution de l'<span class=\"kw-bio\">haptoglobine</span> <strong>en présence</strong> d'un <span class=\"kw-def\">syndrome inflammatoire</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Carence martiale</span></td><td>Diminution de la <span class=\"kw-bio\">ferritine</span> <strong>en l'absence</strong> de <span class=\"kw-def\">syndrome inflammatoire</span></td></tr>\n          <tr><td><span class=\"kw-etio\">CIVD</span></td><td>Diminution du <span class=\"kw-bio\">fibrinogène</span> possible <strong>même en présence</strong> d'un <span class=\"kw-def\">syndrome inflammatoire</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Grossesse</span></td><td>Augmentation des <span class=\"kw-bio\">fractions du complément</span> <strong>même en l'absence</strong> de <span class=\"kw-def\">syndrome inflammatoire</span></td></tr>\n          <tr><td><span class=\"kw-etio\">MAI par complexes immuns</span></td><td>Dépôts de complexes immuns activant la voie classique du <span class=\"kw-bio\">complément</span> → <span class=\"kw-alerte\">hypocomplémentémie de consommation</span> (baisse du <span class=\"kw-bio\">C3</span>, C4, CH50) : <span class=\"kw-def\">lupus</span> systémique, vascularites en <span class=\"kw-clinique\">poussée</span>, cryoglobulinémies, <span class=\"kw-def\">endocardite</span>, glomérulonéphrite</td></tr>\n          <tr><td><span class=\"kw-etio\">Syndrome néphrotique</span></td><td>Diminution de l'<span class=\"kw-bio\">orosomucoïde</span> possible <strong>même en présence</strong> d'un <span class=\"kw-def\">syndrome inflammatoire</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Tocilizumab</span></td><td><span class=\"kw-ttt\">Anticorps anti-récepteur de l'IL-6</span> : empêche l'augmentation de la synthèse hépatique des protéines de l'inflammation → <span class=\"kw-alerte\">dosage de la CRP non interprétable</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Réflexe.</strong> Devant une <span class=\"kw-bio\">VS augmentée sans augmentation des protéines de l'inflammation</span>, réaliser : <span class=\"kw-bio\">hémogramme</span> + <span class=\"kw-bio\">ionogramme</span> + <span class=\"kw-bio\">électrophorèse des protéines sériques</span> (rechercher une anémie, une hypergammaglobulinémie monoclonale ou polyclonale).</div>","frequence":0},{"id":"185-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les complications d’un syndrome inflammatoire prolongé","contenu":"<table >\n        <thead><tr><th>Cible</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Vasculaire</strong></td><td><span class=\"kw-alerte\">Risque thrombo-embolique</span><br><span class=\"kw-alerte\">IDM, AVC</span> : par <span class=\"kw-etio\">athérosclérose</span> accélérée et insulinorésistance</td></tr>\n          <tr><td><strong>Muscle et os</strong></td><td><span class=\"kw-alerte\">Ostéoporose</span> : par augmentation de la résorption osseuse<br><span class=\"kw-alerte\">Dénutrition et sarcopénie</span> : diminution de la force et de la <span class=\"kw-clinique\">masse</span> musculaires</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Amylose AA</strong> (amylose <span class=\"kw-etio\">inflammatoire</span>, <em>amyloid associated</em>).\n        <ul>\n          <li><strong>Mécanisme :</strong> dépôts extracellulaires anormaux de <span class=\"kw-def\">protéine AA</span>, issue du clivage de la <span class=\"kw-def\">protéine SAA</span> sécrétée lors d'un <span class=\"kw-def\">syndrome inflammatoire</span> ; le produit de dégradation se dépose sous forme fibrillaire dans <span class=\"kw-clinique\">les</span> tissus.</li>\n          <li><strong>Pathologies <span class=\"kw-clinique\">les</span> plus à risque :</strong> <span class=\"kw-def\">polyarthrite rhumatoïde</span>, <span class=\"kw-def\">spondyloarthrite</span>, maladie de Still, maladies auto-inflammatoires.</li>\n          <li><strong>Manifestations :</strong> <span class=\"kw-alerte\">atteinte rénale</span> (la plus fréquente — à dépister dans tout <span class=\"kw-def\">syndrome inflammatoire</span> chronique) ; atteinte cardiaque ; atteinte digestive.</li>\n          <li><strong>Diagnostic histologique :</strong> <span class=\"kw-bio\">biopsie</span> de graisse abdominale, de glandes salivaires accessoires, ou <span class=\"kw-bio\">biopsies</span> d'organes.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 221 — <span class=\"kw-etio\">Athérome</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 259 — <span class=\"kw-bio\">Protéinurie</span> - <span class=\"kw-def\">syndrome néphrotique</span></em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-objectifs-0-12-0.php","label":"Collège COFER — Item (objectifs)"}],"cards":[{"i":"2e73f6922c08","n":185,"o":"185-1","u":"Définition","t":"Connaître la définition de la réaction inflammatoire","q":"Quelle est la définition de la réaction inflammatoire ?","a":"<p>La réaction inflammatoire est un <strong>processus de défense</strong> de l'<strong>immunité naturelle</strong> (immunité innée), survenant suite à une <strong>agression exogène ou endogène</strong>.</p>"},{"i":"5af73e25de58","n":185,"o":"185-1","u":"Définition","t":"Connaître la définition de la réaction inflammatoire","q":"Comment la réaction inflammatoire peut-elle être caractérisée en termes de localisation et de durée ?","a":"<p>Elle peut être <strong>localisée ou systémique</strong> et peut être <strong>aiguë ou chronique</strong>.</p>"},{"i":"60d3164686fd","n":185,"o":"185-1","u":"Définition","t":"Connaître la définition de la réaction inflammatoire","q":"Quel rôle joue la réaction inflammatoire dans la réponse de l'organisme ?","a":"<p>Elle constitue la <strong>première ligne de réponse</strong> de l'organisme et se met en place en <strong>quelques heures</strong>.</p>"},{"i":"d5981ebd3e31","n":185,"o":"185-1","u":"Définition","t":"Connaître la définition de la réaction inflammatoire","q":"Quelles peuvent être les conséquences des déterminants biologiques de la réaction inflammatoire ?","a":"<p>Les déterminants biologiques de la réaction inflammatoire peuvent entraîner des <strong>symptômes cliniques</strong> et, à long terme, des <strong>complications</strong>.</p>"},{"i":"1a6522ad650e","n":185,"o":"185-3","u":"Diagnostic positif","t":"Connaître les signes cliniques d’inflammation et leurs conséquences","q":"Quels médiateurs sont responsables de la chaleur, de la rougeur et du gonflement lors d'une inflammation ?","a":"La <strong>chaleur</strong> (calor), la <strong>rougeur</strong> (rubor) et le <strong>gonflement</strong> (tumor) lors de l'inflammation sont principalement dus à l'action de <strong>médiateurs vasoactifs</strong>."},{"i":"4cb023c139c6","n":185,"o":"185-3","u":"Diagnostic positif","t":"Connaître les signes cliniques d’inflammation et leurs conséquences","q":"Quelles sont les trois manifestations cliniques qui composent l'altération de l'état général (AEG) souvent observée en cas d'inflammation prolongée ?","a":"En cas d'inflammation prolongée, l'altération de l'état général (AEG) se manifeste par les « 3 A » :\n<ul>\n<li>L'<strong>amaigrissement</strong>.</li>\n<li>L'<strong>anorexie</strong>.</li>\n<li>L'<strong>asthénie</strong>.</li>\n</ul>"},{"i":"aeb103071d9d","n":185,"o":"185-3","u":"Diagnostic positif","t":"Connaître les signes cliniques d’inflammation et leurs conséquences","q":"Quels sont les quatre signes cliniques locaux cardinaux de l'inflammation, identifiés par Celse ?","a":"Les quatre signes cliniques locaux cardinaux de l'inflammation sont :\n<ul>\n<li>La <strong>douleur (dolor)</strong>.</li>\n<li>La <strong>chaleur (calor)</strong>.</li>\n<li>La <strong>rougeur (rubor)</strong>.</li>\n<li>Le <strong>gonflement (tumor)</strong>.</li>\n</ul>\nCes signes ne sont visibles que si l'organe touché est superficiel, comme la peau ou une articulation."},{"i":"be20e4eb7b09","n":185,"o":"185-3","u":"Diagnostic positif","t":"Connaître les signes cliniques d’inflammation et leurs conséquences","q":"Quel médiateur est un acteur majeur de la douleur dans le cadre de la réaction inflammatoire ?","a":"La <strong>bradykinine</strong> est un médiateur qui stimule les voies nociceptives, induisant ainsi la <strong>douleur</strong> caractéristique de l'inflammation."},{"i":"d99ab7d939c4","n":185,"o":"185-3","u":"Diagnostic positif","t":"Connaître les signes cliniques d’inflammation et leurs conséquences","q":"Quel signe clinique général majeur est médiatisé par les cytokines lors d'une réaction inflammatoire ?","a":"La <strong>fièvre</strong> est un signe clinique général majeur de l'inflammation, induite par l'action des <strong>cytokines</strong> sur l'<strong>hypothalamus</strong>."},{"i":"480ff6147c2b","n":185,"o":"185-4","u":"Diagnostic positif","t":"Connaître les principaux marqueurs biologiques d’un syndrome inflammatoire","q":"Quels sont les marqueurs biologiques de première intention systématiquement recherchés pour le diagnostic d'un syndrome inflammatoire en pratique courante ?","a":"<p>En première intention, pour le diagnostic d'un syndrome inflammatoire, il faut rechercher les marqueurs suivants :</p><ul><li>Un <strong>hémogramme</strong>.</li><li>La <strong>CRP</strong> (C-Reactive Protein).</li><li>La <strong>VS</strong> (vitesse de sédimentation), selon les centres.</li></ul>"},{"i":"8073234c2955","n":185,"o":"185-4","u":"Diagnostic positif","t":"Connaître les principaux marqueurs biologiques d’un syndrome inflammatoire","q":"Quelles sont les caractéristiques principales de la CRP dans le cadre du diagnostic d'un syndrome inflammatoire ?","a":"<p>La <strong>CRP</strong> (C-Reactive Protein) présente les caractéristiques suivantes :</p><ul><li>C'est une protéine produite par le <strong>foie</strong>.</li><li>Son élévation est <strong>rapide</strong> (dès <strong>6-12 heures</strong>).</li><li>Sa demi-vie est <strong>courte</strong> (<strong>24 heures</strong>).</li><li>C'est le marqueur de <strong>référence</strong> du syndrome inflammatoire.</li><li>Elle peut être augmentée en cas d'obésité (jusqu'à <strong>30 mg/L</strong>).</li></ul>"},{"i":"a1dc072cd0a3","n":185,"o":"185-4","u":"Diagnostic positif","t":"Connaître les principaux marqueurs biologiques d’un syndrome inflammatoire","q":"Quels facteurs peuvent modifier la vitesse de sédimentation (VS) en dehors de tout syndrome inflammatoire ?","a":"<p>Plusieurs facteurs peuvent modifier la vitesse de sédimentation (VS) en dehors de tout syndrome inflammatoire :</p><ul><li><strong>VS augmentée</strong> : anémie, hémolyse (test de Coombs direct positif), hémodilution (fin de grossesse, insuffisance cardiaque), macrocytose, diabète, hypercholestérolémie, obésité, insuffisance rénale, syndrome néphrotique, hypergammaglobulinémie monoclonale ou polyclonale.</li><li><strong>VS diminuée</strong> : polyglobulie (la VS varie à l'inverse de l'hématocrite), hémoconcentration, microcytose, drépanocytose, cachexie, hyperviscosité, hyperleucocytose &gt; 50 G/L, hypofibrinogénémie congénitale, cryoglobulinémie, corticothérapie à fortes doses.</li></ul>"},{"i":"c70748f394e5","n":185,"o":"185-4","u":"Diagnostic positif","t":"Connaître les principaux marqueurs biologiques d’un syndrome inflammatoire","q":"Dans quelles situations la Procalcitonine est-elle un marqueur utile pour le diagnostic d'un syndrome inflammatoire ?","a":"<p>La <strong>Procalcitonine</strong> est utile dans les situations suivantes :</p><ul><li>C'est un marqueur d'inflammation d'origine <strong>infectieuse</strong> (bactérienne, parasitaire systémique comme le paludisme, ou fongique).</li><li>Elle a une cinétique très rapide dès <strong>H3</strong> (demi-vie <strong>&lt; 24 heures</strong>).</li><li>Elle n'augmente pas ou peu lors des infections virales, des infections cloisonnées (abcès) ni des maladies inflammatoires non infectieuses.</li><li>Sa valeur initiale a une <strong>valeur pronostique</strong> dans le <strong>sepsis</strong> en urgence.</li></ul>"},{"i":"e69869a60653","n":185,"o":"185-4","u":"Diagnostic positif","t":"Connaître les principaux marqueurs biologiques d’un syndrome inflammatoire","q":"Quelles sont les caractéristiques principales de la vitesse de sédimentation (VS) et ses limites dans le diagnostic d'un syndrome inflammatoire ?","a":"<p>La <strong>vitesse de sédimentation</strong> (VS) présente les caractéristiques suivantes :</p><ul><li>C'est un marqueur de cinétique <strong>lente</strong> (demi-vie de <strong>4 à 6 jours</strong>).</li><li>La technique de mesure de référence est la méthode de <strong>Westergren</strong>.</li><li>Sa sensibilité est de <strong>50 %</strong> et sa spécificité de <strong>97 %</strong>.</li><li>Ses valeurs normales varient selon l'âge et le sexe (homme = âge/2 ; femme = (âge + 10)/2).</li></ul><p>La VS est de moins en moins utilisée en raison de sa cinétique lente et de sa mauvaise spécificité. Elle garde un intérêt dans le suivi des <strong>rhumatismes inflammatoires chroniques</strong> (score <strong>DAS28</strong>).</p>"},{"i":"05810194d6eb","n":185,"o":"185-6","u":"Diagnostic positif","t":"Connaître les manifestations biologiques de la réaction inflammatoire","q":"Quelles sont les caractéristiques morphologiques de l'anémie inflammatoire et comment évoluent-elles dans le temps ?","a":"<p>L'anémie inflammatoire est d'abord <strong>normocytaire et normochrome</strong>. Après <strong>6 à 8 semaines</strong>, elle peut devenir <strong>microcytaire</strong> (rarement &lt; 70 fL) et <strong>hypochrome</strong>.</p>"},{"i":"1736140a9372","n":185,"o":"185-6","u":"Diagnostic positif","t":"Connaître les manifestations biologiques de la réaction inflammatoire","q":"Quelle est la physiopathologie de l'anémie inflammatoire ?","a":"<p>L'anémie inflammatoire est causée par l'action des <strong>cytokines pro-inflammatoires</strong> (IL-1, TNFα, IFNγ) qui entraînent :</p><ul><li>Une <strong>inhibition de l'érythropoïèse</strong> et une diminution de la synthèse et de l'action de l'<strong>EPO</strong> (érythropoïétine).</li><li>Une augmentation de la synthèse hépatique d'<strong>hepcidine</strong>, qui piège le fer dans les macrophages.</li><li>Une augmentation de l'<strong>érythrophagocytose</strong> par les macrophages, diminuant la demi-vie des globules rouges.</li></ul>"},{"i":"878e6e604a19","n":185,"o":"185-6","u":"Diagnostic positif","t":"Connaître les manifestations biologiques de la réaction inflammatoire","q":"Quels sont les paramètres biologiques clés permettant de distinguer une anémie inflammatoire d'une anémie ferriprive et d'une anémie mixte ?","a":"<ul><li><strong>Ferritinémie</strong> : <strong>élevée</strong> ou normale dans l'anémie inflammatoire, effondrée dans l'anémie ferriprive.</li><li><strong>Transferrine</strong> et <strong>CTF</strong> (capacité totale de fixation) : <strong>diminuées</strong> dans l'anémie inflammatoire, augmentées dans l'anémie ferriprive.</li><li><strong>Fer sérique</strong> et <strong>coefficient de saturation</strong> : tous deux diminués dans les deux types d'anémie.</li><li><strong>Récepteur soluble de la transferrine (RsTF)</strong> : <strong>augmentation</strong> en cas de carence martiale (anémie ferriprive ou mixte), et <strong>normal</strong> dans l'anémie inflammatoire pure.</li></ul>"},{"i":"a1d2e6c0b328","n":185,"o":"185-6","u":"Diagnostic positif","t":"Connaître les manifestations biologiques de la réaction inflammatoire","q":"Quelles sont les modifications de l'électrophorèse des protéines sériques au cours d'une réaction inflammatoire ?","a":"<p>On observe :</p><ul><li>Une <strong>hypoalbuminémie</strong>.</li><li>Une <strong>hyper-α1-globulinémie</strong> et <strong>hyper-α2-globulinémie</strong>, avec généralement <strong>α2 &gt; α1</strong>.</li><li>Les <strong>β-globulines</strong> sont inchangées ou légèrement diminuées (due à la baisse de la transferrine).</li><li>La migration du <strong>fibrinogène</strong> en β et de la <strong>CRP</strong> en γ a peu d'influence notable sur le tracé.</li></ul>"},{"i":"a3bc2a367f97","n":185,"o":"185-6","u":"Diagnostic positif","t":"Connaître les manifestations biologiques de la réaction inflammatoire","q":"Comment l'hémogramme est-il modifié lors d'une réaction inflammatoire ?","a":"<ul><li><strong>Globules rouges</strong> : Anémie, initialement <strong>normocytaire/normochrome</strong>, puis <strong>microcytaire/hypochrome</strong> après 6 à 8 semaines.</li><li><strong>Plaquettes</strong> : <strong>Thrombocytose</strong> (via l'IL-6), proportionnelle à la durée de la réaction inflammatoire (jusqu'à 1000 G/L).</li><li><strong>Formule leucocytaire</strong> :<br/><ul><li><strong>Polynucléaires neutrophiles (PNN)</strong> : marqueur très précoce (surtout si cause bactérienne).</li><li><strong>Monocytose</strong> : marqueur précoce (surtout si cause bactérienne).</li><li><strong>Leucopénie</strong> : possible en cas de sepsis.</li><li><strong>Éosinopénie + leucocytose &gt; 10 G/L</strong> : oriente vers une infection bactérienne ou une prise de corticoïdes.</li></ul></li></ul>"},{"i":"f2c9f5541e94","n":185,"o":"185-6","u":"Diagnostic positif","t":"Connaître les manifestations biologiques de la réaction inflammatoire","q":"Quel est le piège classique à connaître concernant la ferritinémie dans l'anémie mixte (carence martiale + syndrome inflammatoire) ?","a":"<p>Le piège est que l'<strong>élévation de la ferritinémie</strong>, induite par le syndrome inflammatoire, peut <strong>masquer une carence martiale</strong> associée. Dans ce cas, l'<strong>augmentation du récepteur soluble de la transferrine (RsTF)</strong> permet de diagnostiquer la carence martiale, ce que la ferritinémie seule ne permet pas.</p>"},{"i":"0436c0255503","n":185,"o":"185-8","u":"Étiologies","t":"Connaître les principales étiologies","q":"Citez les principales maladies génétiques (syndromes auto-inflammatoires) qui peuvent provoquer une réaction inflammatoire.","a":"<p>Ces maladies génétiques sont dues à une anomalie de l'immunité innée, se présentant avec des fièvres récurrentes inexpliquées, des manifestations articulaires et cutanées (<strong>placard érysipéloïde</strong>), des sérites et des signes abdominaux. Les principales sont :</p><ul><li>La <strong>fièvre méditerranéenne familiale (FMF)</strong></li><li>Le <strong>TRAPS (TNF Receptor-Associated Periodic Syndrome)</strong></li></ul>"},{"i":"06f38c103928","n":185,"o":"185-8","u":"Étiologies","t":"Connaître les principales étiologies","q":"Quelles sont les principales maladies inflammatoires et auto-immunes pouvant être à l'origine d'une réaction inflammatoire?","a":"<ul><li>Les <strong>connectivites</strong> (ex: lupus érythémateux systémique)</li><li>Les <strong>rhumatismes inflammatoires</strong> (ex: polyarthrite rhumatoïde, spondyloarthropathies)</li><li>Les <strong>vascularites</strong> (inflammation des vaisseaux sanguins)</li></ul>"},{"i":"5076e9886224","n":185,"o":"185-8","u":"Étiologies","t":"Connaître les principales étiologies","q":"Quelles autres étiologies générales et non spécifiques peuvent entraîner une réaction inflammatoire?","a":"<ul><li>Les <strong>thromboses vasculaires</strong> (ex: thrombose veineuse profonde, embolie pulmonaire)</li><li>Certains <strong>médicaments</strong> (induisant une réaction inflammatoire ou une hypersensibilité)</li><li>Les <strong>traumatismes</strong> (chocs physiques, brûlures, interventions chirurgicales)</li></ul>"},{"i":"8402509e2da4","n":185,"o":"185-8","u":"Étiologies","t":"Connaître les principales étiologies","q":"Quelles sont les étiologies infectieuses de la réaction inflammatoire?","a":"<p>Les causes infectieuses représentent <strong>50%</strong> des syndromes inflammatoires. Elles sont variées et peuvent inclure des infections bactériennes, virales, parasitaires ou fongiques.</p>"},{"i":"dab6cea1cd0b","n":185,"o":"185-8","u":"Étiologies","t":"Connaître les principales étiologies","q":"Quelles sont les étiologies tumorales de la réaction inflammatoire?","a":"<p>Les étiologies tumorales peuvent être des <strong>hémopathies</strong> (leucémies, lymphomes, myélomes) ou des <strong>cancers solides</strong> (carcinomes, sarcomes).</p>"}]};